CREATE TABLE IF NOT EXISTS urls (code VARCHAR(32) PRIMARY KEY, target VARCHAR(2048) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP, hits BIGINT DEFAULT 0, active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS clicks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(32) NOT NULL, clicked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflows (id VARCHAR(36) PRIMARY KEY, scenario VARCHAR(32) NOT NULL, requirement VARCHAR(4000) NOT NULL, state VARCHAR(32) NOT NULL, version INT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (workflow_id VARCHAR(36) NOT NULL, name VARCHAR(64) NOT NULL, dependency VARCHAR(256), status VARCHAR(32) NOT NULL, attempts INT DEFAULT 0, max_attempts INT DEFAULT 2, output VARCHAR(4000), PRIMARY KEY(workflow_id,name));
CREATE TABLE IF NOT EXISTS audits (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workflow_id VARCHAR(36) NOT NULL, event VARCHAR(64) NOT NULL, detail VARCHAR(4000), happened_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approvals (workflow_id VARCHAR(36) NOT NULL, task_name VARCHAR(64) NOT NULL, decision VARCHAR(16) NOT NULL, actor VARCHAR(128), reason VARCHAR(1000), PRIMARY KEY(workflow_id,task_name));
